{
  "product": "HerculeRadar",
  "documentation": "https://herculeradar.com/docs",
  "openapi": "https://herculeradar.com/openapi.json",
  "fullContract": "https://herculeradar.com/llms-full.txt",
  "envelope": {
    "success": "{ data, meta: { capability, requestId, idempotencyReplayed, docs } }",
    "error": "{ error: { code, message, requestId, docs, details?, retryAfter? } }"
  },
  "scopes": [
    {
      "group": "projects",
      "description": "Project settings and plan",
      "grants": [
        "projects:read",
        "projects:write"
      ]
    },
    {
      "group": "monitors",
      "description": "Tracked keywords and sources",
      "grants": [
        "monitors:read",
        "monitors:write"
      ]
    },
    {
      "group": "mentions",
      "description": "Collected mentions and their triage status",
      "grants": [
        "mentions:read",
        "mentions:write"
      ]
    },
    {
      "group": "alerts",
      "description": "Alert rules",
      "grants": [
        "alerts:read",
        "alerts:write"
      ]
    },
    {
      "group": "usage",
      "description": "Quota and provider spend",
      "grants": [
        "usage:read",
        "usage:write"
      ]
    },
    {
      "group": "webhooks",
      "description": "Webhook endpoints and deliveries",
      "grants": [
        "webhooks:read",
        "webhooks:write"
      ]
    }
  ],
  "tools": [
    {
      "name": "list_projects",
      "description": "List the projects this credential can reach. Start here when you do not know the project id.",
      "scope": "projects:read",
      "annotations": {
        "title": "List projects",
        "readOnlyHint": true,
        "destructiveHint": false,
        "idempotentHint": true,
        "openWorldHint": false
      },
      "docs": "https://herculeradar.com/docs/reference/list_projects"
    },
    {
      "name": "create_project",
      "description": "Create a workspace for a brand. Only needed once per brand you monitor.",
      "scope": "projects:write",
      "annotations": {
        "title": "Create project",
        "readOnlyHint": false,
        "destructiveHint": false,
        "idempotentHint": false,
        "openWorldHint": false
      },
      "docs": "https://herculeradar.com/docs/reference/create_project"
    },
    {
      "name": "list_monitors",
      "description": "List what is currently being watched: keywords, aliases, sources and whether each monitor is active.",
      "scope": "monitors:read",
      "annotations": {
        "title": "List monitors",
        "readOnlyHint": true,
        "destructiveHint": false,
        "idempotentHint": true,
        "openWorldHint": false
      },
      "docs": "https://herculeradar.com/docs/reference/list_monitors"
    },
    {
      "name": "create_monitor",
      "description": "Start watching a brand, product or competitor. Include every spelling people actually use — the domain and the @handle as well as the name — because matching is literal.",
      "scope": "monitors:write",
      "annotations": {
        "title": "Create monitor",
        "readOnlyHint": false,
        "destructiveHint": false,
        "idempotentHint": false,
        "openWorldHint": false
      },
      "docs": "https://herculeradar.com/docs/reference/create_monitor"
    },
    {
      "name": "update_monitor",
      "description": "Change a monitor’s keywords, sources or active state. Only the fields you pass change.",
      "scope": "monitors:write",
      "annotations": {
        "title": "Update monitor",
        "readOnlyHint": false,
        "destructiveHint": false,
        "idempotentHint": true,
        "openWorldHint": false
      },
      "docs": "https://herculeradar.com/docs/reference/update_monitor"
    },
    {
      "name": "delete_monitor",
      "description": "Permanently remove a monitor. Mentions already collected are kept. Prefer update_monitor with active:false if the user may want it back.",
      "scope": "monitors:write",
      "annotations": {
        "title": "Delete monitor",
        "readOnlyHint": false,
        "destructiveHint": true,
        "idempotentHint": true,
        "openWorldHint": false
      },
      "docs": "https://herculeradar.com/docs/reference/delete_monitor"
    },
    {
      "name": "list_mentions",
      "description": "The main read tool. Returns collected posts newest first, already classified. Call with no arguments for the latest, or filter by category, sentiment, urgency, source or a named time window. Page with the returned nextCursor.",
      "scope": "mentions:read",
      "annotations": {
        "title": "List mentions",
        "readOnlyHint": true,
        "destructiveHint": false,
        "idempotentHint": true,
        "openWorldHint": false
      },
      "docs": "https://herculeradar.com/docs/reference/list_mentions"
    },
    {
      "name": "get_mention",
      "description": "Fetch one mention in full, with its AI classification and a link to the original post.",
      "scope": "mentions:read",
      "annotations": {
        "title": "Get mention",
        "readOnlyHint": true,
        "destructiveHint": false,
        "idempotentHint": true,
        "openWorldHint": false
      },
      "docs": "https://herculeradar.com/docs/reference/get_mention"
    },
    {
      "name": "update_mention_status",
      "description": "Move a mention through triage. Use done once it has been handled and ignored when it is not really about the brand.",
      "scope": "mentions:write",
      "annotations": {
        "title": "Update mention status",
        "readOnlyHint": false,
        "destructiveHint": false,
        "idempotentHint": true,
        "openWorldHint": false
      },
      "docs": "https://herculeradar.com/docs/reference/update_mention_status"
    },
    {
      "name": "get_mention_analytics",
      "description": "Counts for a window — totals, relevance rate, how many need attention, and breakdowns by category, sentiment and source. Use this to answer \"how are we doing\" without paging the whole feed.",
      "scope": "mentions:read",
      "annotations": {
        "title": "Get mention analytics",
        "readOnlyHint": true,
        "destructiveHint": false,
        "idempotentHint": true,
        "openWorldHint": false
      },
      "docs": "https://herculeradar.com/docs/reference/get_mention_analytics"
    },
    {
      "name": "list_alerts",
      "description": "List alert rules — what triggers a notification and where it is sent.",
      "scope": "alerts:read",
      "annotations": {
        "title": "List alerts",
        "readOnlyHint": true,
        "destructiveHint": false,
        "idempotentHint": true,
        "openWorldHint": false
      },
      "docs": "https://herculeradar.com/docs/reference/list_alerts"
    },
    {
      "name": "create_alert",
      "description": "Notify an email address or https webhook when a matching mention arrives. Empty filter arrays mean \"any\".",
      "scope": "alerts:write",
      "annotations": {
        "title": "Create alert",
        "readOnlyHint": false,
        "destructiveHint": false,
        "idempotentHint": false,
        "openWorldHint": false
      },
      "docs": "https://herculeradar.com/docs/reference/create_alert"
    },
    {
      "name": "delete_alert",
      "description": "Permanently remove an alert rule. Notifications stop immediately.",
      "scope": "alerts:write",
      "annotations": {
        "title": "Delete alert",
        "readOnlyHint": false,
        "destructiveHint": true,
        "idempotentHint": true,
        "openWorldHint": false
      },
      "docs": "https://herculeradar.com/docs/reference/delete_alert"
    },
    {
      "name": "get_usage",
      "description": "Plan, mentions used against the quota, and what collection cost this period. Check before creating monitors if the user is near their limit.",
      "scope": "usage:read",
      "annotations": {
        "title": "Get usage",
        "readOnlyHint": true,
        "destructiveHint": false,
        "idempotentHint": true,
        "openWorldHint": false
      },
      "docs": "https://herculeradar.com/docs/reference/get_usage"
    }
  ]
}
